<template>
  <view class="page-shell taiyi-page">
    <view class="intro"><view class="intro-copy"><text class="eyebrow">卜 · 问事与记录</text><text class="page-heading">以岁为序，<br />把积数算清。</text><text class="page-caption">太乙金镜岁计 · 本机计算与研习档案</text></view><CatCompanion class="intro-cat" :mood="snapshot ? 'complete' : 'thinking'" /></view>
    <text class="privacy-note">计算只在本机进行 · 点击保存才留档 · 不上传、不发送给 AI</text>
    <view class="scope-note"><text class="scope-title">本版是一种固定岁计</text><text>{{ TAIYI_YEAR_POLICY }}</text><text class="scope-title epoch-label">先说明积年从何而来</text><text>{{ TAIYI_EPOCH_NOTE }}</text></view>
    <AppButton class="text-button archive-link" @click="scrollTo('#taiyi-archive')">查看本机太乙档案 · {{ records.length }} / 30 ↗</AppButton>

    <view id="taiyi-form" class="panel">
      <text class="panel-title">留下这次岁计的资料</text>
      <view class="form-group"><text class="form-label">记录名称</text><input v-model="input.name" class="form-input" maxlength="40" placeholder="例如：金镜年计规则练习" aria-label="太乙记录名称，必填" /></view>
      <view class="form-group"><text class="form-label">所求岁年</text><input v-model="input.year" class="form-input" inputmode="numeric" maxlength="4" placeholder="以公元年标识，例如 724 或 2026" aria-label="所求岁年，公元1至9999，非具体公历时刻，必填" /><text class="small-copy">支持 1–9999；不支持公元前与 0 年。年份是所求传统岁年的标识，请先确定要核对的岁年；本页不从某一天自动判断归年。</text></view>
      <AppButton class="text-button" @click="fillAnchor">填入开元十二年甲子（724）锚例</AppButton>
      <view class="form-group"><text class="form-label">底本备注 <text class="optional">可选</text></text><input v-model="input.sourceNote" class="form-input" maxlength="200" placeholder="你正在阅读的版本、页码或对照来源" aria-label="底本备注，仅记录，不改变固定算法" /><text class="small-copy">备注不改变本版纪元或取法；其他积年法需另作核对。</text></view>
      <view class="form-group"><text class="form-label">所记事项 <text class="optional">可选</text></text><textarea v-model="input.question" class="form-textarea" :maxlength="500" placeholder="记下想核对的步骤或读书所得。" aria-label="所记事项，最多500字" /></view>
      <text v-if="formError" class="error-note" role="alert">{{ formError }}</text>
      <AppButton class="btn-primary full-button" @click="generate">按固定金镜岁计计算</AppButton><text class="small-copy">展示盘面与算式，不生成吉凶、灾异、胜负或行动建议。</text>
      <AppButton class="text-button" @click="newDraft">新建空白表单</AppButton>
    </view>

    <view v-if="snapshot" id="taiyi-result" class="panel result-panel">
      <view class="panel-heading"><text class="eyebrow">{{ savedRecord ? '保存时的完整快照' : '本次生成 · 尚未保存' }}</text><text class="result-method">阳局 {{ snapshot.board.ju }}</text></view>
      <text class="panel-title record-title" selectable>{{ snapshot.input.name }}</text>
      <text class="reference-time">所求岁年 {{ snapshot.input.year }} · {{ snapshot.yearGanZhi }}</text>
      <text class="small-copy">太岁 {{ snapshot.taiSui }} · 合神 {{ snapshot.combinedSpirit }} · 第 {{ snapshot.ji }} 纪第 {{ snapshot.cycle60 }} 年</text>
      <view class="accumulated"><text class="lesson-label">本版积年</text><text class="accumulated-number">{{ formatNumber(snapshot.accumulated) }}</text><text class="small-copy">1,937,281 +（{{ snapshot.input.year }} − 724）</text></view>
      <view class="summary-strip"><text>太乙 {{ palaceName(snapshot.board.taiyi) }} · 入宫第 {{ snapshot.board.palaceYear }} 年（{{ snapshot.board.governance }}）</text><text>天目 {{ snapshot.board.skyEyeName }} · {{ snapshot.board.skyEye }}</text><text>始击 {{ snapshot.board.strikeName }} · {{ snapshot.board.strike }} · 计神 {{ snapshot.board.calculationSpirit }}</text></view>
      <text v-if="snapshot.board.status === 'partial'" class="error-note" role="status">本局主算存在待校勘文字，主算及主将留空；其他确定位置已计算，下方保留冲突与步骤。</text>

      <text class="section-label">太乙九宫</text><text class="small-copy board-hint">上南下北 · 本版乾一、离二、艮三、震四、兑六、坤七、坎八、巽九</text>
      <view class="nine-palaces" aria-label="太乙九宫，上南下北，采用太乙专用宫数">
        <view v-for="cell in displayPalaces" :key="cell.number" class="palace" :class="{ 'taiyi-palace': cell.number === snapshot.board.taiyi, 'center-palace': cell.number === 5 }" :aria-label="`${cell.trigram}${cell.number}宫，${cell.direction}，${cell.markers.join('、') || '无本版标记'}`"><view class="palace-heading"><text>{{ cell.trigram }}{{ cell.number }}</text><text>{{ cell.direction }}</text></view><text v-for="marker in cell.markers" :key="marker" class="palace-marker" :class="{ 'taiyi-marker': marker === '太乙' }">{{ marker }}</text><text v-if="!cell.markers.length" class="palace-empty">{{ cell.number === 5 ? '太乙不入中五' : '—' }}</text></view>
      </view>

      <text class="section-label">十六神位置</text><text class="small-copy board-hint">按子起顺序列出；天目、始击、计神保留独立位置，不把间神挤入九宫。</text>
      <view class="spirits-grid"><view v-for="spirit in snapshot.board.spirits" :key="spirit.position" class="spirit-cell" :class="{ 'active-spirit': spirit.markers.length }"><text class="spirit-position">{{ spirit.position }}</text><text class="spirit-name">{{ spirit.name }}</text><text class="spirit-marker">{{ spirit.markers.join(' · ') || '—' }}</text></view></view>

      <text class="section-label">主客算与将位</text>
      <view v-for="row in calculationRows" :key="row.label" class="calculation-card"><view class="panel-heading"><text class="calculation-title">{{ row.label }}算</text><text class="count-number">{{ row.calculation.count === null ? '待校勘' : row.calculation.count }}</text></view><text class="small-copy">{{ row.label }}大将 {{ row.calculation.general === null ? '待校勘' : palaceName(row.calculation.general) }} · {{ row.label }}参将 {{ row.calculation.assistant === null ? '待校勘' : palaceName(row.calculation.assistant) }}</text><text v-if="row.calculation.unresolved" class="error-note" role="status">{{ row.calculation.unresolved }}</text><text class="calculation-steps">{{ row.calculation.steps.map(step => `${step.position}${step.kind === '间神起一' ? '（间神）' : ''} ${step.amount}`).join(' ＋ ') }}</text><text class="small-copy">{{ row.calculation.unresolved ? '以上仅列步骤供核对，未将其合计视作已确认的主算。' : `合计 ${row.calculation.count}；不计终点太乙宫。起点与太乙同在正宫时取该宫本数。` }}</text></view>

      <text class="section-label">把除法步骤展开</text><text class="small-copy">各周期分别对本版积年作整数除法。余数为 0 表示该周期末位，不回退到首位；下一岁年才进入首位。</text>
      <view class="division-table" aria-label="积年除法步骤"><view class="division-row division-heading"><text>除数</text><text>商</text><text>余数</text><text>周内序</text></view><view v-for="row in snapshot.divisions" :key="row.divisor" class="division-row"><text>{{ row.divisor }}</text><text>{{ row.quotient }}</text><text>{{ row.remainder }}</text><text>{{ row.ordinal }}</text></view></view>
      <view class="rule-trace"><text class="scope-title">本盘计算依据</text><text v-for="line in snapshot.board.explanation" :key="line" class="small-copy">{{ line }}</text></view>
      <text class="small-copy changed-note">{{ snapshot.epoch.note }}</text>
      <view class="facts-list"><view><text class="fact-label">底本备注</text><text selectable>{{ snapshot.input.sourceNote || '未记录' }}</text></view><view><text class="fact-label">所记事项</text><text selectable>{{ snapshot.input.question || '未记录' }}</text></view></view>
      <text v-if="formChanged" class="small-copy changed-note">上方表单与此快照不同；这里展示原盘，使用新资料请重新计算。</text>
      <text v-if="saveError" class="error-note" role="alert">{{ saveError }}</text><text v-if="storageError" class="error-note" role="alert">档案暂不可读，已停止保存，请在下方重试读取。</text>
      <AppButton class="btn-primary full-button" :disabled="Boolean(savedRecord) || Boolean(storageError)" @click="saveCurrent">{{ savedRecord ? '这张盘已保存' : '保存当前显示的岁计盘' }}</AppButton>
      <view class="action-row"><AppButton class="action-button" @click="copyToForm">复制资料到表单</AppButton><AppButton v-if="savedRecord" class="action-button" @click="exportOne(savedRecord)">导出这份 JSON</AppButton></view>
      <text class="small-copy rule-footer">{{ snapshot.method }} · {{ snapshot.ruleVersion }}<br />{{ savedRecord ? `保存于 ${displayTime(savedRecord.savedAt)} UTC；读取未重排。` : '保留输入、纪元、算式、盘面及未定字段；保存时间不参与岁计。' }}</text>
    </view>

    <view id="taiyi-archive" class="panel"><view class="panel-heading"><text class="panel-title">本机太乙档案</text><text class="small-copy">{{ records.length }} / {{ TAIYI_RECORD_LIMIT }}</text></view><text class="small-copy">与账号分开存放。清理应用数据会丢失记录，导出可作备份；文件包含你填写的事项与底本备注。</text>
      <AppButton class="text-button" @click="loadRecords">刷新档案列表</AppButton><text v-if="storageError" class="error-note" role="alert">{{ storageError }}</text><text v-if="actionError" class="error-note" role="alert">{{ actionError }}</text>
      <text v-if="!records.length && !storageError" class="small-copy empty-note">还没有太乙档案。计算后，点击保存即可留下完整快照。</text>
      <view v-for="record in records" :key="record.id" class="record-row"><AppButton class="record-open" :disabled="Boolean(storageError)" @click="openRecord(record)"><text class="record-name">{{ record.snapshot.input.name }}</text><text class="small-copy">所求岁年 {{ record.snapshot.input.year }} · {{ record.snapshot.yearGanZhi }}</text><text class="record-meta">阳局 {{ record.snapshot.board.ju }} · {{ record.snapshot.board.status === 'partial' ? '含待校勘字段 · ' : '' }}查看原快照 ↗</text></AppButton><AppButton class="text-button delete-button" :disabled="Boolean(storageError)" :aria-label="`删除太乙档案：${record.snapshot.input.name}`" @click="confirmDelete(record)">删除</AppButton></view>
      <AppButton class="btn-secondary full-button" :disabled="!records.length || Boolean(storageError)" @click="exportAll">导出全部太乙档案 JSON</AppButton><text class="small-copy">浏览器发起下载；其他端复制 JSON 后，请粘贴到文件中保存。</text>
    </view>
    <text v-if="notice" class="notice" role="status" aria-live="polite">{{ notice }}</text>

    <view class="panel source-panel"><AppButton class="disclosure-button" :aria-expanded="sourcesOpen" @click="sourcesOpen = !sourcesOpen"><text>底本、固定古例与支持范围</text><text aria-hidden="true">{{ sourcesOpen ? '−' : '＋' }}</text></AppButton><view v-if="sourcesOpen" class="source-content"><text class="small-copy">先手抄 23 个原典阳局固定值，再依卷一、二步骤独立实现；另核对 4 个古例将位。第 39、50 局主算与原书表有冲突，相关字段留空待校勘。全部 72 局另做结构和周期检查，不将自洽当作全量外部正确性证明。</text><text class="small-copy">只支持上述岁计规则；不含月、日、时、分计、命法、其他积年法、五福、大小游、八门、神煞或自动占断。这里的传统神名、理天理地理人属于规则标记，不是实测天体位置或现实预测。</text><view v-for="source in TAIYI_SOURCES" :key="source.url"><AppButton class="text-button" @click="openSource(source.url)">{{ source.title }} ↗</AppButton><text class="small-copy">{{ source.usage }}</text></view><text class="small-copy rule-footer">本项目独立实现；不依赖远程排盘服务，不调用候选引擎的数据包或解释模块。原典在线转录仍可能有异文，需连同本版固定口径阅读。</text></view></view>
    <text class="footer-note">把来源与疑点一起留下，才方便下一次核对。</text>
  </view>
</template>

<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
import { onShow } from '@dcloudio/uni-app'
import AppButton from '@/components/AppButton.vue'
import CatCompanion from '@/components/CatCompanion.vue'
import { createTaiyiSnapshot, emptyTaiyiInput, TAIYI_EPOCH_NOTE, TAIYI_YEAR_POLICY, TAIYI_SOURCES, type TaiyiSnapshot } from '@/domain/taiyi'
import { createTaiyiRepository, exportTaiyiRecord, TAIYI_RECORD_LIMIT, type TaiyiRecord } from '@/domain/taiyi/repository'
import { exportJson } from '@/utils/export-json'
const input = ref(emptyTaiyiInput()), snapshot = ref<TaiyiSnapshot | null>(null), savedRecord = ref<TaiyiRecord | null>(null), records = ref<TaiyiRecord[]>([])
const formChanged = ref(false), sourcesOpen = ref(false), formError = ref(''), saveError = ref(''), storageError = ref(''), actionError = ref(''), notice = ref('')
const today = new Date(Date.now() + 8 * 3600000).toISOString().slice(0, 10)
const displayPalaces = computed(() => snapshot.value ? [9, 2, 7, 4, 5, 6, 3, 8, 1].map(number => snapshot.value!.board.palaces[number - 1]) : [])
const calculationRows = computed(() => snapshot.value ? [{ label: '主', calculation: snapshot.value.board.host }, { label: '客', calculation: snapshot.value.board.guest }] : [])
const repository = createTaiyiRepository({ get: key => uni.getStorageSync(key), set: (key, value) => uni.setStorageSync(key, value) })
const message = (error: unknown) => error instanceof Error ? error.message : '本次操作未完成，请重试。'
function displayTime(value: string) { return value.replace('T', ' ').slice(0, 19) }
function formatNumber(value: number) { return String(value).replace(/\B(?=(\d{3})+(?!\d))/g, ',') }
function palaceName(number: number) { const cell = snapshot.value?.board.palaces[number - 1]; return cell ? `${cell.trigram}${number}宫` : '' }
function scrollTo(selector: string) { nextTick(() => uni.pageScrollTo({ selector, duration: 200 })) }
watch(input, () => { formChanged.value = Boolean(snapshot.value); formError.value = '' }, { deep: true, flush: 'sync' })
function fillAnchor() { input.value.year = '724'; if (!input.value.name) input.value.name = '开元十二年甲子锚例' }
function loadRecords() { try { records.value = repository.list(); storageError.value = ''; return true } catch (error) { storageError.value = message(error); return false } }
onShow(loadRecords)
function generate() { formError.value = ''; saveError.value = ''; notice.value = ''; try { snapshot.value = createTaiyiSnapshot(input.value); savedRecord.value = null; formChanged.value = false; scrollTo('#taiyi-result') } catch (error) { formError.value = message(error) } }
function saveCurrent() { if (!snapshot.value || savedRecord.value || storageError.value) return; saveError.value = ''; notice.value = ''; try { savedRecord.value = repository.save(snapshot.value); notice.value = loadRecords() ? '已保存当前显示的完整岁计盘。' : '快照已写入，但列表暂未读出；请重试刷新。' } catch (error) { saveError.value = message(error) } }
function newDraft() { snapshot.value = null; savedRecord.value = null; input.value = emptyTaiyiInput(); formChanged.value = false; formError.value = ''; saveError.value = ''; notice.value = '已建立空白表单，已保存的档案仍在下方。'; scrollTo('#taiyi-form') }
function copyToForm() { if (!snapshot.value) return; input.value = JSON.parse(JSON.stringify(snapshot.value.input)); formChanged.value = false; notice.value = '资料已复制到表单，修改后可重新计算。'; scrollTo('#taiyi-form') }
function openRecord(record: TaiyiRecord) { savedRecord.value = JSON.parse(JSON.stringify(record)); snapshot.value = JSON.parse(JSON.stringify(record.snapshot)); formChanged.value = JSON.stringify(input.value) !== JSON.stringify(record.snapshot.input); saveError.value = ''; actionError.value = ''; notice.value = ''; scrollTo('#taiyi-result') }
async function download(data: unknown, filename: string) { actionError.value = ''; notice.value = ''; try { const method = await exportJson(data, filename); notice.value = method === 'download' ? '已发起 JSON 文件下载，请在下载目录确认。' : '档案 JSON 已复制，请粘贴到文件中保存。' } catch (error) { actionError.value = message(error) } }
function exportOne(record: TaiyiRecord) { try { return download(exportTaiyiRecord(record), `oasis-taiyi-${record.id}.json`) } catch (error) { actionError.value = message(error) } }
function exportAll() { try { return download(repository.exportAll(), `oasis-taiyi-collection-${today}.json`) } catch (error) { actionError.value = message(error) } }
function confirmDelete(record: TaiyiRecord) {
  uni.showModal({ title: '删除这份太乙档案', content: `确定删除「${record.snapshot.input.name}」？删除后无法撤销，其他档案不受影响。`, confirmText: '删除', cancelText: '保留', success: response => {
    if (!response.confirm) return
    try { records.value = repository.remove(record.id); if (savedRecord.value?.id === record.id) { savedRecord.value = null; snapshot.value = null }; actionError.value = ''; notice.value = '已删除这份本机太乙档案。' } catch (error) { actionError.value = message(error) }
  }, fail: () => { actionError.value = '未能打开删除确认，请重试；未删除档案。' } })
}
function openSource(url: string) {
  // #ifdef H5
  window.open(url, '_blank', 'noopener,noreferrer')
  return
  // #endif
  // #ifndef H5
  uni.setClipboardData({ data: url, success: () => { notice.value = '来源链接已复制，可在浏览器阅读。' }, fail: () => { actionError.value = '来源链接复制失败，请重试。' } })
  // #endif
}
</script>

<style scoped>
