ont-size: 13px; margin-top: 18px; }.text-button { min-height: 42px; margin: 4px 0 0; padding: 8px 0; background: transparent; color: #9068a4; text-align: left; font-size: 12px; line-height: 1.8; white-space: normal; overflow-wrap: anywhere; }.text-button::after, .record-open::after, .disclosure-button::after { border: 0; }.archive-link { padding-bottom: 16px; }.result-panel { background: linear-gradient(150deg, #fff, #fdfaff); }.result-method { font-size: 18px; color: #856199; font-weight: 650; }.reference-time { font-size: 13px; line-height: 1.8; margin-top: 9px; color: #755985; overflow-wrap: anywhere; }.accumulated { background: #f9f5ee; padding: 15px; border-radius: 14px; margin-top: 15px; }.accumulated-number { display: block; font-size: 30px; line-height: 1.6; color: #997c59; letter-spacing: 1px; }.summary-strip { padding: 12px; margin-top: 12px; background: #f7f1fa; border-radius: 12px; color: #80658e; font-size: 11px; line-height: 1.9; }.summary-strip > text { display: block; }.section-label { color: #785e88; font-size: 14px; margin-top: 22px; font-weight: 600; }.board-hint { margin: 8px 0 10px; }.nine-palaces { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); border: 1px solid #decee9; border-radius: 12px; overflow: hidden; background: #fff; }.palace { min-width: 0; padding: 10px 7px; min-height: 108px; box-sizing: border-box; border-right: 1px solid #e8ddef; border-bottom: 1px solid #e8ddef; }.palace:nth-child(3n) { border-right: 0; }.palace:nth-child(n + 7) { border-bottom: 0; }.palace-heading { display: flex; flex-wrap: wrap; gap: 1px 5px; justify-content: space-between; color: #a58eb0; font-size: 10px; line-height: 1.5; margin-bottom: 8px; }.palace-marker { display: block; color: #997bac; font-size: 11px; line-height: 1.9; }.taiyi-marker { color: #795688; font-size: 17px; font-weight: 650; }.taiyi-palace { background: #f8f1fc; }.center-palace { background: #fcfafc; }.palace-empty { display: block; color: #b9a8c1; font-size: 9px; margin-t